package main

import (
	"context"
	"encoding/json"
	"log"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

func main() {
	n := maelstrom.NewNode()
	kv := maelstrom.NewLinKV(n)

	// "send" appends a message to a log and returns its offset.
	n.Handle("send", func(msg maelstrom.Message) error {
		var body map[string]any
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}

		key := body["key"].(string)
		val := int(body["msg"].(float64))

		for {
			// Read the current log for this key.
			log, err := kv.Read(context.Background(), key)
			if err != nil {
				// Key does not exist yet.
				log = []any{}
			}
			entries := log.([]any)
			offset := len(entries)
			newEntries := append(entries, []any{offset, val})

			// Atomically append, retrying if someone else appended first.
			err = kv.CompareAndSwap(context.Background(), key, log, newEntries, true)
			if err == nil {
				return n.Reply(msg, map[string]any{
					"type":   "send_ok",
					"offset": offset,
				})
			}
		}
	})

	// "poll" reads messages from several logs, each beginning at a given offset.
	n.Handle("poll", func(msg maelstrom.Message) error {
		var body map[string]any
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}

		offsets := body["offsets"].(map[string]any)
		msgs := map[string]any{}

		for key, offsetVal := range offsets {
			off := int(offsetVal.(float64))
			log, err := kv.Read(context.Background(), key)
			if err != nil {
				// No such log.
				continue
			}
			entries := log.([]any)
			if off < len(entries) {
				msgs[key] = entries[off:]
			}
		}

		return n.Reply(msg, map[string]any{
			"type": "poll_ok",
			"msgs": msgs,
		})
	})

	// "commit_offsets" records the highest offset a reader has processed.
	n.Handle("commit_offsets", func(msg maelstrom.Message) error {
		var body map[string]any
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}

		offsets := body["offsets"].(map[string]any)
		for key, offsetVal := range offsets {
			off := int(offsetVal.(float64))
			if err := kv.Write(context.Background(), "commit:"+key, off); err != nil {
				return err
			}
		}

		return n.Reply(msg, map[string]any{
			"type": "commit_offsets_ok",
		})
	})

	// "list_committed_offsets" returns the committed offset for each key.
	n.Handle("list_committed_offsets", func(msg maelstrom.Message) error {
		var body map[string]any
		if err := json.Unmarshal(msg.Body, &body); err != nil {
			return err
		}

		keys := body["keys"].([]any)
		offsets := map[string]any{}

		for _, keyVal := range keys {
			key := keyVal.(string)
			off, err := kv.ReadInt(context.Background(), "commit:"+key)
			if err == nil {
				offsets[key] = off
			}
		}

		return n.Reply(msg, map[string]any{
			"type": "list_committed_offsets_ok",
			"offsets": offsets,
		})
	})

	if err := n.Run(); err != nil {
		log.Fatal(err)
	}
}

